library(shiny)

# Interactive companion to Actividade.qmd.  It intentionally uses only Shiny
# and base R so it is easy to run on a school computer.

# Keep the small teaching dataset inside the app. This makes the exported
# Shinylive application a single, self-contained source file.
population <- data.frame(
  habitat = c(4,5,8,5,5,8,6,2,4,4,7,6,6,5,4,9,6,1,6,4,3,5,3,4,4,
              2,7,5,3,8,6,4,7,7,7,6,6,5,4,4,4,5,2,9,7,3,4,4,7,5,6,5,5,
              8,5,8,2,6,5,5,6,4,4,3,3,6,6,5,7,9,4,0,7,4,4,7,4,3,5,5,
              5,6,4,6,5,6,7,6,4,7,7,6,5,4,8,4,9,8,5,3),
  animals = c(3,2,5,2,3,5,3,3,2,3,4,3,4,2,3,5,2,0,3,2,2,2,1,2,2,
              2,3,4,2,4,3,4,4,3,4,2,3,3,3,3,2,4,3,4,3,3,3,3,5,3,4,3,
              3,4,4,4,1,4,3,3,4,3,2,2,2,4,4,4,4,5,3,2,4,2,3,4,3,3,
              3,3,3,3,3,2,2,3,4,3,1,4,4,5,3,4,4,3,5,4,3,3),
  id = 1:100
)

animal_symbols <- function(n) {
  if (n <= 0) return("—")
  paste(rep("🐟", n), collapse = "")
}

ui <- fluidPage(
  tags$head(
    tags$meta(charset = "utf-8"),
    tags$style(HTML("
      :root { --ink:#16302b; --green:#18765a; --mint:#e9f7ef; --gold:#f2b84b; --paper:#fffdf8; }
      body { background:#f4f0e7; color:var(--ink); font-family:system-ui,-apple-system,'Segoe UI',sans-serif; }
      .container-fluid { max-width:1280px; padding:0 24px 40px; }
      .hero { margin:0 -24px 22px; padding:24px 28px; color:white;
              background:linear-gradient(125deg,#123b33,#1d7a5d); }
      .hero h1 { margin:0 0 5px; font-weight:800; letter-spacing:-.03em; }
      .hero p { margin:0; opacity:.92; font-size:17px; }
      .panel-card { background:var(--paper); border:1px solid #ded8cb; border-radius:16px;
                    padding:18px; box-shadow:0 4px 16px rgba(28,43,36,.07); margin-bottom:18px; }
      .step { display:inline-block; background:var(--gold); color:#3d2a00; border-radius:999px;
              padding:4px 10px; font-weight:800; font-size:12px; letter-spacing:.05em; }
      .counter { font-size:22px; font-weight:800; margin:8px 0; }
      .hint { color:#56645f; font-size:14px; }
      .quadrat-grid { display:grid; grid-template-columns:repeat(10,minmax(0,1fr)); gap:6px; }
      .quadrat { display:flex; aspect-ratio:1 / 1; min-width:0; padding:4px 2px; border:2px solid #b7c4bd;
                 border-radius:9px; text-align:center; text-decoration:none!important; color:var(--ink)!important;
                 background:#f8fbf7; transition:.12s ease; overflow:hidden; flex-direction:column;
                 align-items:center; justify-content:center; }
      .quadrat:hover { border-color:var(--green); transform:translateY(-1px); }
      .quadrat.selected { background:#fff1c9; border-color:#d89516; box-shadow:0 0 0 2px #ffe7a2; }
      .q-id { display:block; font-size:9px; line-height:10px; opacity:.58; }
      .q-value { display:block; font-weight:850; font-size:19px; line-height:21px; }
      .q-label { display:block; font-size:9px; line-height:10px; text-transform:uppercase; letter-spacing:.03em; }
      .q-dots { display:block; max-width:100%; font-size:11px; line-height:12px; letter-spacing:-3px;
                overflow-wrap:anywhere; color:#1876a1; }
      .btn { border-radius:10px; font-weight:700; }
      .btn-primary { background:var(--green); border-color:var(--green); }
      .metric-row { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin:12px 0; }
      .metric { border-radius:13px; padding:14px; background:var(--mint); border:1px solid #cce5d6; }
      .metric.design { background:#fff3d7; border-color:#f0d69c; }
      .metric.truth { background:#f3eafd; border-color:#d9c4ef; }
      .metric .number { display:block; font-size:30px; font-weight:900; line-height:1.1; }
      .metric .label { font-size:12px; color:#52605b; }
      .formula { background:#eef1ef; border-radius:10px; padding:10px 12px; font-family:ui-monospace,monospace; }
      .result-note { padding:10px 13px; border-left:5px solid var(--green); background:#edf7f2; margin-top:12px; }
      .field-layout { display:grid; grid-template-columns:minmax(0,3fr) minmax(210px,1fr); gap:16px; align-items:start; }
      .record-sheet { background:#fff; border:1px solid #d6d1c5; border-radius:12px; padding:10px; }
      .record-sheet h4 { margin:2px 0 8px; font-size:16px; }
      .record-sheet table { width:100%; margin:0; font-size:12px; }
      .record-sheet th { background:#e9f7ef; text-align:center; }
      .record-sheet td { text-align:center; }
      .record-empty { color:#66736e; font-size:12px; padding:8px 2px; }
      .nav-tabs>li>a { color:var(--green); font-weight:700; }
      @media(max-width:1000px) { .field-layout{grid-template-columns:1fr} }
      @media(max-width:800px) { .quadrat-grid{grid-template-columns:repeat(5,minmax(0,1fr))} .metric-row{grid-template-columns:1fr} }
    "))
  ),
  div(class = "hero",
      h1("🔎 Quantos animais há?"),
      p("Uma população escondida, 100 quadrados e apenas 10 oportunidades para observar.")),
  fluidRow(
    column(3,
      div(class = "panel-card",
          span(class = "step", "PASSO 1 · PLANEAR"),
          h3("Escolhe a amostra"),
          radioButtons("sampling", NULL,
                       choices = c("Eu escolho os quadrados" = "manual",
                                   "Amostra aleatória" = "random"),
                       selected = "manual"),
          actionButton("draw", "Sortear 10", class = "btn-primary"),
          actionButton("clear", "Recomeçar"),
          hr(),
          radioButtons("side", "O que está virado para cima?",
                       choices = c("Habitat" = "habitat", "Animais" = "animals"),
                       selected = "habitat", inline = TRUE),
          uiOutput("sample_counter"),
          p(class = "hint", "Na atividade real, cada cartão tem o habitat de um lado e os animais do outro. Escolhe cartões pelo habitat e depois vira-os para contar.")),
      div(class = "panel-card",
          span(class = "step", "DESAFIO"),
          h4("Antes de calcular…"),
          p("A tua amostra representa bem os 100 quadrados? O que poderá acontecer se escolheres apenas habitats com valores altos?"))
    ),
    column(9,
      div(class = "panel-card",
          span(class = "step", "A POPULAÇÃO · 10 × 10"),
          h3("Clica em 10 quadrados"),
          div(class = "field-layout",
              uiOutput("quadrat_grid"),
              div(class = "record-sheet",
                  h4("📝 Registo da amostra"),
                  uiOutput("sample_log"))))
    )
  ),
  div(class = "panel-card",
      span(class = "step", "PASSO 2 · ESTIMAR"),
      h3("Duas maneiras de passar da amostra à população"),
      conditionalPanel(
        condition = "output.ready == false",
        div(class = "result-note", "Seleciona 10 quadrados para desbloquear os cálculos.")
      ),
      conditionalPanel(
        condition = "output.ready == true",
        tabsetPanel(
          tabPanel("Comparar estimativas",
            uiOutput("metrics"), uiOutput("calculation"),
            actionButton("reveal", "Revelar a população verdadeira", class = "btn-primary")
          ),
          tabPanel("Regressão e previsão", br(), plotOutput("regression_plot", height = "430px"),
                   p(class = "hint", "Pontos laranja: amostra. Pontos claros: população, mostrados apenas para ajudar a compreender a simulação. A linha é ajustada só aos 10 quadrados observados.")),
          tabPanel("Quadrado a quadrado", br(), tableOutput("prediction_table"))
        )
      ))
)

server <- function(input, output, session) {
  selected <- reactiveVal(integer(0))
  truth_revealed <- reactiveVal(FALSE)

  observeEvent(input$clear, {
    selected(integer(0))
    truth_revealed(FALSE)
  })

  observeEvent(input$draw, {
    selected(sample(population$id, 10))
    truth_revealed(FALSE)
    updateRadioButtons(session, "side", selected = "animals")
  })

  observeEvent(input$sampling, {
    if (identical(input$sampling, "random")) {
      selected(sample(population$id, 10))
      truth_revealed(FALSE)
      updateRadioButtons(session, "side", selected = "animals")
    }
  }, ignoreInit = TRUE)

  observe({
    lapply(population$id, function(i) {
      observeEvent(input[[paste0("q_", i)]], {
        req(identical(input$sampling, "manual"))
        now <- selected()
        if (i %in% now) {
          selected(setdiff(now, i))
        } else if (length(now) < 10) {
          # Keep click order: it becomes the sample sequence shown in the
          # field record beside the study area.
          selected(c(now, i))
        } else {
          showNotification("Já escolheste 10 quadrados. Retira um antes de escolher outro.", type = "warning")
        }
        truth_revealed(FALSE)
      }, ignoreInit = TRUE)
    })
  })

  output$sample_counter <- renderUI({
    n <- length(selected())
    div(class = "counter", paste0(n, " / 10 escolhidos"),
        div(class = "progress", style = "height:8px; margin-top:8px;",
            div(class = "progress-bar", role = "progressbar", style = paste0("width:", 10*n, "%; background:#18765a"))))
  })

  output$quadrat_grid <- renderUI({
    show_animals <- identical(input$side, "animals")
    cards <- lapply(seq_len(nrow(population)), function(row) {
      d <- population[row, ]
      is_selected <- d$id %in% selected()
      value <- if (show_animals) d$animals else d$habitat
      label <- if (show_animals) "animais" else "habitat"
      dots <- if (show_animals) tags$span(class = "q-dots", animal_symbols(d$animals)) else NULL
      actionLink(paste0("q_", d$id),
                 class = paste("quadrat", if (is_selected) "selected" else ""),
                 tags$span(class = "q-id", paste("Q", d$id)),
                 tags$span(class = "q-value", value), dots,
                 tags$span(class = "q-label", label))
    })
    div(class = "quadrat-grid", cards)
  })

  output$sample_log <- renderUI({
    ids <- selected()
    if (!length(ids)) {
      return(div(class = "record-empty",
                 "Os registos aparecem aqui à medida que escolhes quadrados."))
    }
    d <- population[match(ids, population$id), , drop = FALSE]
    tags$table(
      class = "table table-condensed table-bordered",
      tags$thead(tags$tr(
        tags$th("Quadrado"),
        tags$th("Habitat"),
        tags$th("Animais")
      )),
      tags$tbody(lapply(seq_len(nrow(d)), function(j) {
        tags$tr(
          tags$td(j),
          tags$td(d$habitat[j]),
          tags$td(d$animals[j])
        )
      }))
    )
  })

  ready <- reactive(length(selected()) == 10)
  output$ready <- reactive(ready())
  outputOptions(output, "ready", suspendWhenHidden = FALSE)

  results <- reactive({
    req(ready())
    samp <- population[population$id %in% selected(), , drop = FALSE]
    # A pupil can deliberately choose ten cards with the same habitat value.
    # In that case a slope cannot be learned, so the honest model is the sample
    # mean (an intercept-only model).
    fit <- if (length(unique(samp$habitat)) > 1) {
      lm(animals ~ habitat, data = samp)
    } else {
      lm(animals ~ 1, data = samp)
    }
    pred <- pmax(0, predict(fit, newdata = population))
    list(sample = samp, fit = fit, prediction = pred,
         design = mean(samp$animals) * nrow(population),
         model = sum(pred), truth = sum(population$animals))
  })

  observeEvent(input$reveal, truth_revealed(TRUE))

  output$metrics <- renderUI({
    r <- results()
    div(class = "metric-row",
      div(class = "metric design", span(class = "number", round(r$design)), span(class = "label", "Estimativa pelo desenho")),
      div(class = "metric", span(class = "number", round(r$model)), span(class = "label", "Estimativa pelo modelo")),
      div(class = "metric truth",
          span(class = "number", if (truth_revealed()) r$truth else "?"),
          span(class = "label", "Total verdadeiro"))
    )
  })

  output$calculation <- renderUI({
    r <- results(); b <- coef(r$fit)
    model_formula <- if (length(b) > 1) {
      sprintf("animais previstos = %.2f %+.2f × habitat", b[1], b[2])
    } else {
      sprintf("animais previstos = %.2f (não há variação de habitat na amostra)", b[1])
    }
    tagList(
      h4("Estimativa baseada no desenho"),
      div(class = "formula", sprintf("(%d animais observados ÷ 10 quadrados) × 100 = %.0f", sum(r$sample$animals), r$design)),
      p("Funciona bem quando os 10 quadrados formam uma amostra aleatória representativa."),
      h4("Estimativa baseada no modelo"),
      div(class = "formula", model_formula),
      p("Aplicamos esta relação aos valores de habitat dos 100 quadrados e somamos as previsões."),
      if (truth_revealed()) {
        div(class = "result-note",
            sprintf("Erros absolutos: desenho = %.0f animais; modelo = %.0f animais. Experimenta outra amostra: o resultado muda!",
                    abs(r$design-r$truth), abs(r$model-r$truth)))
      }
    )
  })

  output$regression_plot <- renderPlot({
    r <- results()
    plot(population$habitat, population$animals, pch = 21, bg = "#d9e4dd", col = "#91a299",
         xlab = "Característica do habitat", ylab = "Número de animais",
         main = "A amostra ensina o modelo", xlim = range(population$habitat), ylim = c(0, max(population$animals)+1))
    points(r$sample$habitat, r$sample$animals, pch = 21, bg = "#f2b84b", col = "#9b6500", cex = 1.7, lwd = 2)
    if (length(coef(r$fit)) > 1) {
      abline(r$fit, col = "#18765a", lwd = 3)
    } else {
      abline(h = coef(r$fit)[1], col = "#18765a", lwd = 3)
    }
    legend("topleft", c("100 quadrados", "10 observados", "modelo da amostra"),
           pch = c(21,21,NA), pt.bg = c("#d9e4dd", "#f2b84b", NA), lty = c(NA,NA,1),
           col = c("#91a299", "#9b6500", "#18765a"), lwd = c(NA,NA,3), bty = "n")
  })

  output$prediction_table <- renderTable({
    r <- results()
    data.frame(Quadrado = population$id,
               Habitat = population$habitat,
               Observado = ifelse(population$id %in% selected(), population$animals, "—"),
               `Previsão do modelo` = round(r$prediction, 1), check.names = FALSE)
  }, striped = TRUE, bordered = FALSE, spacing = "s", width = "100%")
}

shinyApp(ui, server)
